        positions = get_sunroof_and_sunshade_position()
        sunroof_pos = positions.get('sunroof_percentage')
        sunshade_pos = positions.get('sunshade_percentage')
        if sunroof_pos is None or sunshade_pos is None:
            respond('I could not retrieve the sunroof or sunshade position. Please try again.')
