```python
munich_id = get_location_id_by_location_name(location_name='Munich')
if munich_id is None:
    respond('I could not find Munich. Please check the destination name.')
else:
    nav_state = get_current_navigation_state()
    start = nav_state.get('current_location_id') or nav_state.get('start_location_id')
    if not start:
        respond('I need a current location to plan the route.')
    else:
        routes = get_routes(start_location=start, destination=munich_id)
        if not routes:
            respond('No routes were found to Munich.')
        else:
            fastest = min(routes, key=lambda r: r.get('duration'))
            toll_free = [r for r in routes if not r.get('toll')]
            if toll_free:
                fastest_no_toll = min(toll_free, key=lambda r: r.get('duration'))
            else:
                fastest_no_toll = None
            route_options = '\n'.join([f"Route {i+1}: duration {r.get('duration')} minutes, toll {r.get('toll')}" for i, r in enumerate(routes)])
            if any(r.get('toll') for r in routes):
                respond(f"I found the following routes: {route_options}. The fastest route includes tolls. I will select the fastest route without tolls.")
                if fastest_no_toll:
                    start_navigation(route_id=fastest_no_toll['route_id'])
                    respond('Navigation started on the fastest route without tolls.')
                else:
                    respond('All routes include tolls. I will start the fastest route.')
                    start_navigation(route_id=fastest['route_id'])
                    respond('Navigation started on the fastest route.')
            else:
                respond(f"I found the following routes: {route_options}. I will select the fastest route.")
                start_navigation(route_id=fastest['route_id'])
                respond('Navigation started on the fastest route.')
```

