{"code": "location_id = get_location_id_by_location_name(location_name='Munich')
if location_id is None:
    respond('I could not find Munich in the navigation database.')
else:
    current_state = get_current_navigation_state()
    routes = get_routes(start_location=current_state['current_location'], destination=location_id)
    if not routes:
        respond('No routes found to Munich.')
    else:
        # Present route options and choose fastest, but avoid tolls if mentioned
        fastest_route = min(routes, key=lambda r: r['travel_time'])
        toll_free_routes = [r for r in routes if not r.get('has_toll', False)]
        if toll_free_routes and fastest_route.get('has_toll', False):
            # Mention toll roads and choose fastest toll-free
            best_route = min(toll_free_routes, key=lambda r: r['travel_time'])
            respond('I found several routes to Munich. Some include toll roads. The fastest toll-free route takes ' + str(best_route['travel_time']) + ' minutes.')
        else:
            best_route = fastest_route
            respond('I found several routes to Munich. The fastest route takes ' + str(best_route['travel_time']) + ' minutes.')
        start_navigation(route_id=best_route['route_id'])"}

