{"code": "climate = get_climate_settings()
passenger = climate.get('passenger', {})
driver = climate.get('driver', {})
if not passenger:
    respond('Unable to read passenger climate settings.')
else:
    # Sync temperature
    target_temp = passenger.get('temperature')
    if target_temp is not None and 16.0 <= target_temp <= 28.0:
        set_temperature(temperature=target_temp, zone='driver')
    else:
        respond('Passenger temperature is out of range; cannot sync.')
        target_temp = None
    # Sync fan speed
    target_fan = passenger.get('fan_speed')
    if target_fan is not None and 0 <= target_fan <= 7:
        set_fan_speed(level=target_fan)
    else:
        respond('Passenger fan speed is out of range; cannot sync.')
        target_fan = None
    # Sync AC on/off
    ac_on = passenger.get('air_conditioning')
    if ac_on is not None:
        set_air_conditioning(on=ac_on)
    else:
        respond('Passenger AC state not available; cannot sync.')
    # Sync heating (if available, but here we assume AC handles heating)
    # Since no separate heating function, we rely on temperature and AC.
    # Respond with summary if all synced successfully
    if target_temp is not None and target_fan is not None:
        respond('Driver zone climate synced to passenger settings.')
    else:
        respond('Partial sync completed; some settings could not be synced.')"}

